printf '%s\n' \
  '{"timestamp":"2026-01-14T10:00:00Z","embedding_text":"alpha","key":"k1"}' \
  '{"timestamp":"2026-01-14T11:00:00Z","embedding_text":"alpha","key":"k1"}' \
  '{"timestamp":"2026-01-14T12:00:00Z","embedding_text":"beta","key":"k2"}' \
  > /tmp/ns/acme/papers/2026-01/current.jsonl
printf '%s\n' \
  '{"timestamp":"2026-01-14T09:00:00Z","embedding_text":"gamma","key":"k3"}' \
  '{"timestamp":"2026-01-13T09:00:00Z","embedding_text":"SPURIOUS-OTHER-DAY","key":"kx"}' \
  > /tmp/ns/beta/notes/2026-01/current.jsonl

node dist/cli.js consolidate --target 2026-01-14 --namespaces-root /tmp/ns
